package com.example.domain.model.i18n

internal object DuaAr2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_adhan_response" to DuaText("الرد على الأذان", "لا حول ولا قوة إلا بالله", "يردد ما يقوله المؤذن؛ وعند 'حي على الصلاة' و'حي على الفلاح' يقول هذا", "من أجاب بقلبه دخل الجنة."),
        "dua_adhan_shahadah" to DuaText("بعد شهادة المؤذن", "وأنا أشهد أن لا إله إلا الله وحده لا شريك له وأن محمدا عبده ورسوله، رضيت بالله ربا، وبمحمد رسولا، وبالإسلام دينا", "عند سماع الشهادتين من المؤذن", "تُغفر له ذنوبه."),
        "dua_after_rain" to DuaText("بعد المطر", "مطرنا بفضل الله ورحمته", "بعد هطول المطر", "قائلها مؤمن بالله."),
        "dua_after_witr" to DuaText("بعد الوتر", "سبحان الملك القدوس", "بعد التسليم من الوتر ثلاث مرات، ويرفع صوته في الثالثة", "كان النبي ﷺ يقولها بعد الوتر."),
        "dua_against_enemy_ahzab" to DuaText("ضد جيوش الأعداء", "اللهم منزل الكتاب، سريع الحساب، اهزم الأحزاب، اللهم اهزمهم وزلزلهم", "عند مواجهة العدو — دعاء غزوة الأحزاب", "دعاء النبي ﷺ ضد الأعداء."),
        "dua_ahsin_aqibatana" to DuaText("أحسن عاقبتنا في الأمور كلها", "اللهم أحسن عاقبتنا في الأمور كلها، وأجرنا من خزي الدنيا وعذاب الآخرة", "لحسن العاقبة في كل أمر", "من دعا بها مات محفوظًا من الفتن."),
        "dua_ahyini_ma_kanat" to DuaText("بدلًا من تمني الموت", "اللهم أحيني ما كانت الحياة خيرا لي، وتوفني إذا كانت الوفاة خيرا لي", "عند الابتلاء بدل تمني الموت", "نهى النبي ﷺ عن تمني الموت وعلّم هذا الدعاء."),
        "dua_ajz_kasal_haram" to DuaText("الاستعاذة من العجز والهرم", "اللهم إني أعوذ بك من العجز والكسل، والجبن والهرم، وأعوذ بك من فتنة المحيا والممات، وأعوذ بك من عذاب القبر", "دعاء استعاذة يومي جامع", "من دعاء النبي ﷺ المتكرر."),
        "dua_ala_kulli_hal" to DuaText("الحمد على كل حال", "الحمد لله على كل حال", "عند رؤية أمر مكروه", "كان النبي ﷺ يقولها عند رؤية المكروه."),
        "dua_alimal_ghayb" to DuaText("عالم الغيب والشهادة", "اللهم عالم الغيب والشهادة، فاطر السماوات والأرض، رب كل شيء ومليكه، أشهد أن لا إله إلا أنت، أعوذ بك من شر نفسي، ومن شر الشيطان وشركه", "صباحًا ومساءً وعند النوم — علّمها النبي ﷺ لأبي بكر رضي الله عنه", "الحفظ من شر النفس والشيطان."),
        "dua_allahu_akbar_kabira_2696" to DuaText("كلمات علّمت لأعرابي", "لا إله إلا الله وحده لا شريك له، الله أكبر كبيرا، والحمد لله كثيرا، سبحان الله رب العالمين، لا حول ولا قوة إلا بالله العزيز الحكيم", "كلمة جامعة للذكر والدعاء", "بعدها علّمه النبي ﷺ 'اللهم اغفر لي وارحمني واهدني وارزقني'."),
        "dua_allahu_rabbi" to DuaText("الله الله ربي", "الله الله ربي لا أشرك به شيئا", "عند الهم أو الشدة — علّمها النبي ﷺ لأسماء بنت عميس رضي الله عنها", "التوحيد ملاذ عند الشدة."),
        "dua_amsayna_fitrah" to DuaText("أمسينا على فطرة الإسلام", "أمسينا على فطرة الإسلام، وعلى كلمة الإخلاص، وعلى دين نبينا محمد ﷺ، وعلى ملة أبينا إبراهيم حنيفا مسلما وما كان من المشركين", "في المساء", "تجديد الإيمان كل مساء."),
        "dua_anta_adudi" to DuaText("أنت عضدي ونصيري", "اللهم أنت عضدي ونصيري، بك أحول، وبك أصول، وبك أقاتل", "قبل مواجهة أو تحدٍّ كبير", "كان النبي ﷺ يقولها في القتال."),
        "dua_arafah" to DuaText("أفضل دعاء يوم عرفة", "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير", "يوم عرفة — أفضل الدعاء", "أفضل الدعاء دعاء يوم عرفة."),
        "dua_ascending_descending" to DuaText("الصعود والنزول", "الله أكبر — سبحان الله", "في السفر، التكبير عند الصعود والتسبيح عند النزول", "كان هذا معمول الصحابة رضي الله عنهم في السفر."),
        "dua_aslih_li_dini" to DuaText("أصلح لي ديني ودنياي وآخرتي", "اللهم أصلح لي ديني الذي هو عصمة أمري، وأصلح لي دنياي التي فيها معاشي، وأصلح لي آخرتي التي فيها معادي، واجعل الحياة زيادة لي في كل خير، واجعل الموت راحة لي من كل شر", "إصلاح الدين والدنيا والآخرة معًا", "دعاء النبي ﷺ الجامع."),
        "dua_ati_nafsi_taqwaha" to DuaText("آت نفسي تقواها", "اللهم آت نفسي تقواها، وزكها أنت خير من زكاها، أنت وليها ومولاها", "لإصلاح النفس وتزكيتها", "كان النبي ﷺ يدعو بهذا الدعاء."),
        "dua_ayyub" to DuaText("دعاء أيوب عليه السلام في المرض", "أني مسني الضر وأنت أرحم الراحمين", "عند المرض والابتلاء", "فرّج الله عن أيوب عليه السلام ما كان به من ضر."),
        "dua_bad_character" to DuaText("الاستعاذة من سوء الأخلاق", "اللهم إني أعوذ بك من منكرات الأخلاق، والأعمال، والأهواء", "الاستعاذة من سوء الأخلاق والأعمال والأهواء", "دعاء استعاذة نبوي."),
        "dua_being_praised" to DuaText("عند مدحك من الآخرين", "اللهم لا تؤاخذني بما يقولون، واغفر لي ما لا يعلمون", "عند سماع الثناء على النفس", "طريقة التحصن من الغرور عند المدح."),
        "dua_beneficial_knowledge" to DuaText("العلم النافع والرزق الطيب", "اللهم إني أسألك علما نافعا، ورزقا طيبا، وعملا متقبلا", "بعد صلاة الفجر", "كان النبي ﷺ يقولها بعد سلام الفجر."),
        "dua_bi_ilmikal_ghayb" to DuaText("أحيني ما دامت الحياة خيرًا لي", "اللهم بعلمك الغيب، وقدرتك على الخلق، أحيني ما علمت الحياة خيرا لي، وتوفني إذا علمت الوفاة خيرا لي، اللهم وأسألك خشيتك في الغيب والشهادة، وأسألك كلمة الحق في الرضا والغضب، وأسألك القصد في الفقر والغنى", "جزء من دعاء صلاة عمار بن ياسر رضي الله عنه", "كان النبي ﷺ يدعو بها في صلاته."),
        "dua_closing_eyes" to DuaText("عند تغميض عيني الميت", "اللهم اغفر لفلان، وارفع درجته في المهديين، واخلفه في عقبه في الغابرين، واغفر لنا وله يا رب العالمين، وافسح له في قبره، ونور له فيه", "عند تغميض عيني الميت (مع ذكر اسمه)", "دعا بها النبي ﷺ لأبي سلمة رضي الله عنه."),
        "dua_condolence" to DuaText("التعزية", "إن لله ما أخذ، وله ما أعطى، وكل شيء عنده بأجل مسمى، فلتصبر ولتحتسب", "عند تعزية أهل الميت", "أرسلها النبي ﷺ إلى ابنته."),
        "dua_dogs_barking" to DuaText("سماع نباح الكلاب ليلًا", "أعوذ بالله من الشيطان الرجيم", "عند نباح الكلاب أو نهيق الحمير ليلًا", "إنها ترى ما لا ترون."),
        "dua_dressing" to DuaText("عند لبس الثوب", "الحمد لله الذي كساني هذا الثوب ورزقنيه من غير حول مني ولا قوة", "عند ارتداء الثياب", "بشارة بمغفرة الذنوب السابقة."),
        "dua_eid_greeting" to DuaText("تهنئة العيد", "تقبل الله منا ومنك", "يوم العيد بين المسلمين — عادة الصحابة رضي الله عنهم", "كان الصحابة يتبادلونها يوم العيد."),
        "dua_eid_takbeer" to DuaText("التكبير في طريق العيد", "الله أكبر، الله أكبر، لا إله إلا الله، والله أكبر، الله أكبر، ولله الحمد", "من ليلة العيد إلى صلاة عيد الفطر", "أمر قرآني بإكمال العدة والتكبير (البقرة ٢:١٨٥)."),
        "dua_entering_village" to DuaText("دخول قرية أو مدينة", "اللهم رب السماوات السبع وما أظللن، ورب الأرضين السبع وما أقللن، ورب الشياطين وما أضللن، ورب الرياح وما ذرين، فإنا نسألك خير هذه القرية وخير أهلها، ونعوذ بك من شرها وشر أهلها وشر ما فيها", "قبل الدخول إلى بلدة أو قرية", "كان النبي ﷺ يقولها عند دخول أي بلدة."),
        "dua_evening_blessing" to DuaText("شكر النعم مساءً", "اللهم ما أمسى بي من نعمة أو بأحد من خلقك فمنك وحدك لا شريك لك فلك الحمد ولك الشكر", "ذكر شكر نعم الله في المساء", "حصن المسلم."),
        "dua_evening_witness" to DuaText("إشهاد التوحيد مساءً", "اللهم إني أمسيت أشهدك وأشهد حملة عرشك وملائكتك وجميع خلقك أنك أنت الله لا إله إلا أنت وحدك لا شريك لك وأن محمدا عبدك ورسولك", "يُذكر في الرواية قراءتها أربع مرات مساءً", "حصن المسلم."),
        "dua_fadlika_wa_rahmatik" to DuaText("أسألك من فضلك ورحمتك", "اللهم إني أسألك من فضلك ورحمتك، فإنه لا يملكها إلا أنت", "عند طلب الرزق والرحمة", "دعا بها النبي ﷺ عند نفاد الطعام فجاء الهدية."),
        "dua_faqr_qillah_dhillah" to DuaText("الاستعاذة من الفقر والذلة", "اللهم إني أعوذ بك من الفقر والقلة والذلة، وأعوذ بك من أن أظلم أو أظلم", "للحفظ من الفقر والقلة والذلة", "استعاذة نبوية."),
        "dua_fasting_invited" to DuaText("عند الدعوة وأنت صائم", "إني صائم", "إذا دُعيت للطعام أو نازعك أحد وأنت صائم", "إذا قبل الصائم الدعوة فليدعُ لصاحب الطعام."),
        "dua_fear_people" to DuaText("الخوف من الأعداء أو الظالمين", "اللهم إنا نجعلك في نحورهم، ونعوذ بك من شرورهم", "عند الخوف من شر قوم أو شخص", "كان النبي ﷺ يقولها إذا خاف قومًا."),
        "dua_filal_khayrat" to DuaText("فعل الخيرات وترك المنكرات", "اللهم إني أسألك فعل الخيرات، وترك المنكرات، وحب المساكين، وأن تغفر لي وترحمني، وإذا أردت فتنة قوم فتوفني غير مفتون، أسألك حبك، وحب من يحبك، وحب عمل يقرب إلى حبك", "علّمها الله للنبي ﷺ في المنام", "قال النبي ﷺ: هذا حق فتعلموه وعلموه."),
        "dua_fitnat_ghina_faqr" to DuaText("الاستعاذة من فتنة الغنى والفقر", "اللهم إني أعوذ بك من الكسل والهرم، والمأثم والمغرم، ومن فتنة القبر وعذاب القبر، ومن فتنة النار وعذاب النار، ومن شر فتنة الغنى، وأعوذ بك من فتنة الفقر", "جزء من دعاء الاستعاذة من فتنة القبر والنار", "دعاء استعاذة نبوي جامع."),
        "dua_fitratil_islam" to DuaText("على فطرة الإسلام", "أصبحنا على فطرة الإسلام، وعلى كلمة الإخلاص، وعلى دين نبينا محمد ﷺ، وعلى ملة أبينا إبراهيم حنيفا مسلما وما كان من المشركين", "في الصباح", "تجديد الإيمان كل صباح."),
        "dua_five_things_new_muslim" to DuaText("اغفر وارحم واهد وعافني وارزقني", "اللهم اغفر لي، وارحمني، واهدني، وعافني، وارزقني", "كان النبي ﷺ يعلمها للمسلم الجديد مع الصلاة", "قال النبي ﷺ: هذه الكلمات تجمع لك خير الدنيا والآخرة."),
        "dua_for_one_i_cursed" to DuaText("لمن آذيته بالكلام", "اللهم فأيما مؤمن سببته فاجعل ذلك له قربة إليك يوم القيامة", "إذا سببت أحدًا في غضب", "دعاء النبي ﷺ."),
        "dua_for_who_gave_drink" to DuaText("لمن أطعمك أو سقاك", "اللهم أطعم من أطعمني، واسق من سقاني", "لمن أطعمك أو سقاك", "دعا بها النبي ﷺ للمقداد رضي الله عنه."),
        "dua_four_beloved_words" to DuaText("أحب الكلمات الأربع", "سبحان الله، والحمد لله، ولا إله إلا الله، والله أكبر", "من أحب الكلام إلى الله", "أحب إلى النبي ﷺ مما طلعت عليه الشمس."),
        "dua_ghalabatid_dayn" to DuaText("الاستعاذة من غلبة الدين والأعداء", "اللهم إني أعوذ بك من غلبة الدين، وغلبة العدو، وشماتة الأعداء", "الحفظ من ثقل الدين وغلبة الأعداء", "كان النبي ﷺ يستعيذ من هذه الأمور."),
        "dua_going_to_mosque_nur" to DuaText("الذهاب إلى المسجد (دعاء النور)", "اللهم اجعل في قلبي نورا، وفي بصري نورا، وفي سمعي نورا، وعن يميني نورا، وعن يساري نورا، وفوقي نورا، وتحتي نورا، وأمامي نورا، وخلفي نورا، واجعل لي نورا", "عند الذهاب إلى المسجد لصلاة الفجر", "كان النبي ﷺ يقولها عند خروجه للصلاة."),
        "dua_hadm_gharaq" to DuaText("الاستعاذة من الموت المفاجئ والحوادث", "اللهم إني أعوذ بك من الهدم، وأعوذ بك من التردي، وأعوذ بك من الغرق والحرق والهرم، وأعوذ بك أن يتخبطني الشيطان عند الموت، وأعوذ بك أن أموت في سبيلك مدبرا، وأعوذ بك أن أموت لديغا", "الاستعاذة من الحوادث وسوء الخاتمة", "دعاء استعاذة نبوي."),
        "dua_hajj_la_riya" to DuaText("حج بلا رياء", "اللهم حجة لا رياء فيها ولا سمعة", "عند نية الحج للإخلاص", "دعاء النبي ﷺ عند الحج."),
        "dua_hamdan_kathiran" to DuaText("حمدًا كثيرًا بعد الركوع", "ربنا ولك الحمد حمدا كثيرا طيبا مباركا فيه", "بعد الرفع من الركوع مع 'ربنا لك الحمد'", "تسابق أكثر من ثلاثين ملكًا لكتابتها أولًا."),
        "dua_heavy_rain" to DuaText("عند كثرة المطر", "اللهم حوالينا ولا علينا", "إذا كثر المطر", "بدعاء النبي ﷺ انقشع السحاب."),
        "dua_hubbaka" to DuaText("سؤال محبة الله", "اللهم إني أسألك حبك، وحب من يحبك، والعمل الذي يبلغني حبك، اللهم اجعل حبك أحب إلي من نفسي وأهلي ومن الماء البارد", "دعاء داود عليه السلام الذي ذكره النبي ﷺ", "محبة الله أعظم الثروات."),
        "dua_huda_tuqa" to DuaText("الهدى والتقى والعفاف والغنى", "اللهم إني أسألك الهدى والتقى، والعفاف والغنى", "دعاء النبي ﷺ الجامع المختصر", "أربع نعم أساسية للدين والدنيا."),
        "dua_husn_khatimah" to DuaText("الوفاة على الإسلام (دعاء يوسف عليه السلام)", "فاطر السماوات والأرض أنت وليي في الدنيا والآخرة ۖ توفني مسلما وألحقني بالصالحين", "دعاء لحسن الخاتمة", "دعاء يوسف عليه السلام."),
        "dua_iftar_ibn_umar" to DuaText("الإفطار: برحمتك الواسعة اغفر لي", "اللهم إني أسألك برحمتك التي وسعت كل شيء أن تغفر لي", "عند الإفطار — دعاء عبد الله بن عمرو رضي الله عنهما", "دعاء الصائم عند فطره لا يُرد."),
        "dua_iftar_laka_sumtu" to DuaText("الإفطار: لك صمت", "اللهم لك صمت، وعلى رزقك أفطرت", "عند الإفطار", "معمول به عند الأحناف وجمهور العلماء."),
        "dua_ihdini_saddidni" to DuaText("اهدني وسددني", "اللهم اهدني وسددني", "علّمها النبي ﷺ لعلي رضي الله عنه", "اذكر الهداية بهداية الطريق والسداد باستقامة السهم."),
        "dua_ikfinihim" to DuaText("اكفنيهم بما شئت", "اللهم اكفنيهم بما شئت", "من شر الظالمين — دعاء الغلام أصحاب الأخدود", "نجّى الله الغلام من الظالمين."),
        "dua_ilbas_jadidan" to DuaText("عند رؤية من لبس جديدًا", "البس جديدا، وعش حميدا، ومت شهيدا", "عند رؤية أخيك المسلم بثياب جديدة", "دعا بها النبي ﷺ لعمر رضي الله عنه."),
        "dua_infani_bima_allamtani" to DuaText("انفعني بما علمتني", "اللهم انفعني بما علمتني، وعلمني ما ينفعني، وزدني علما", "عند طلب العلم أو قبل الدراسة", "دعاء العلم النافع والعمل به."),
        "dua_inni_saim" to DuaText("عند الاستفزاز وأنت صائم", "إني صائم، إني صائم", "إذا سبّك أحد أو جادلك وأنت صائم", "الصوم جُنّة، فليقل هذا مرتين."),
        "dua_iqsim_lana_khashyatik" to DuaText("اقسم لنا من خشيتك", "اللهم اقسم لنا من خشيتك ما يحول بيننا وبين معاصيك، ومن طاعتك ما تبلغنا به جنتك، ومن اليقين ما تهون به علينا مصيبات الدنيا، ومتعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا، واجعله الوارث منا، واجعل ثأرنا على من ظلمنا، وانصرنا على من عادانا، ولا تجعل مصيبتنا في ديننا، ولا تجعل الدنيا أكبر همنا ولا مبلغ علمنا، ولا تسلط علينا من لا يرحمنا", "عند القيام من المجلس", "دعاء جامع لخيري الدنيا والآخرة."),
        "dua_ishfi_abdak" to DuaText("لشفاء المريض", "اللهم اشف عبدك ينكأ لك عدوا، أو يمشي لك إلى صلاة", "عند عيادة المريض ادعُ له بهذا", "علّمه النبي ﷺ للمريض."),
        "dua_ism_azam_ahad_samad" to DuaText("اسم الله الأعظم: الأحد الصمد", "اللهم إني أسألك بأني أشهد أنك أنت الله، لا إله إلا أنت، الأحد الصمد، الذي لم يلد ولم يولد، ولم يكن له كفوا أحد", "قال النبي ﷺ إنه سأل الله باسمه الأعظم", "إذا سُئل به أعطى، وإذا دُعي به أجاب."),
        "dua_ism_azam_mannan" to DuaText("اسم الله الأعظم: المنّان", "اللهم إني أسألك بأن لك الحمد، لا إله إلا أنت، المنان، بديع السماوات والأرض، يا ذا الجلال والإكرام، يا حي يا قيوم", "قال النبي ﷺ إن هذا دعا باسم الله الأعظم", "من دعا بهذا الاسم استُجيب له."),
        "dua_istiftah_baid" to DuaText("دعاء الاستفتاح: باعد بيني وبين خطاياي", "اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من الخطايا كما ينقى الثوب الأبيض من الدنس، اللهم اغسل خطاياي بالماء والثلج والبرد", "بعد تكبيرة الإحرام", "كان النبي ﷺ يقولها بين التكبير والقراءة."),
        "dua_istiftah_kabira" to DuaText("الله أكبر كبيرًا، حمدًا كثيرًا", "الله أكبر كبيرا، والحمد لله كثيرا، وسبحان الله بكرة وأصيلا", "عند افتتاح الصلاة", "قال النبي ﷺ: فُتحت لها أبواب السماء."),
        "dua_istisqa" to DuaText("طلب المطر (الاستسقاء)", "اللهم أغثنا، اللهم أغثنا، اللهم أغثنا", "عند انقطاع المطر", "دعا بها النبي ﷺ في خطبة الجمعة فنزل المطر."),
        "dua_istisqa_ibadak" to DuaText("اسق عبادك وبهائمك", "اللهم اسق عبادك وبهائمك، وانشر رحمتك، وأحي بلدك الميت", "طلب المطر (الاستسقاء)", "كان النبي ﷺ يدعو بها للمطر."),
        "dua_jahdil_bala" to DuaText("الاستعاذة من جهد البلاء", "اللهم إني أعوذ بك من جهد البلاء، ودرك الشقاء، وسوء القضاء، وشماتة الأعداء", "الاستعاذة من شدة البلاء وشماتة الأعداء", "كان النبي ﷺ يستعيذ من هذه الأربع."),
        "dua_jamarat" to DuaText("رمي الجمرات", "الله أكبر", "عند رمي كل حصاة", "كان النبي ﷺ يكبر مع كل حصاة."),
        "dua_janaza_adult" to DuaText("صلاة الجنازة (البالغ)", "اللهم اغفر لحينا وميتنا، وشاهدنا وغائبنا، وصغيرنا وكبيرنا، وذكرنا وأنثانا، اللهم من أحييته منا فأحيه على الإسلام، ومن توفيته منا فتوفه على الإيمان", "بعد التكبيرة الثالثة في صلاة الجنازة", "دعاء مسنون للميت البالغ."),
        "dua_janaza_child" to DuaText("صلاة الجنازة (الطفل)", "اللهم اجعله لنا فرطا، واجعله لنا أجرا وذخرا، واجعله لنا شافعا ومشفعا", "في صلاة جنازة الطفل غير البالغ", "معمول به عند الأحناف."),
        "dua_jannah_nar" to DuaText("سؤال الجنة والاستعاذة من النار", "اللهم إني أسألك الجنة، وأعوذ بك من النار", "بعد التشهد أو في كل وقت", "قال النبي ﷺ: ونحن ندندن حول هذا."),
        "dua_jar_su" to DuaText("الاستعاذة من جار السوء", "اللهم إني أعوذ بك من جار السوء في دار المقامة، فإن جار البادية يتحول", "للحفظ من جار السوء", "أمر النبي ﷺ بالاستعاذة منه."),
        "dua_jiddi_wa_hazli" to DuaText("اغفر لي جدي وهزلي", "اللهم اغفر لي جدي وهزلي، وخطئي وعمدي، وكل ذلك عندي", "لمغفرة الذنوب عمدًا وسهوًا", "استغفار النبي ﷺ الجامع."),
        "dua_ju_khiyanah" to DuaText("الاستعاذة من الجوع والخيانة", "اللهم إني أعوذ بك من الجوع فإنه بئس الضجيع، وأعوذ بك من الخيانة فإنها بئست البطانة", "الاستعاذة من الجوع والخيانة", "دعاء النبي ﷺ."),
        "dua_khayri_kullih" to DuaText("كل الخير عاجله وآجله", "اللهم إني أسألك من الخير كله، عاجله وآجله، ما علمت منه وما لم أعلم، وأعوذ بك من الشر كله، عاجله وآجله، ما علمت منه وما لم أعلم، اللهم إني أسألك الجنة وما قرب إليها من قول أو عمل، وأعوذ بك من النار وما قرب إليها من قول أو عمل", "علّمها النبي ﷺ لعائشة رضي الله عنها", "دعاء جامع لكل خير."),
        "dua_kufr_faqr" to DuaText("الاستعاذة من الكفر والفقر", "اللهم إني أعوذ بك من الكفر والفقر، وأعوذ بك من عذاب القبر، لا إله إلا أنت", "صباحًا ومساءً ثلاث مرات", "سمعها أبو بكرة رضي الله عنه من النبي ﷺ."),
        "dua_la_bas_tahur" to DuaText("تسلية المريض: لا بأس طهور", "لا بأس، طهور إن شاء الله", "عند عيادة المريض للتسلية", "كان النبي ﷺ يقولها عند زيارة المريض."),
        "dua_la_hawla_kanz" to DuaText("كنز من كنوز الجنة", "لا حول ولا قوة إلا بالله", "بكثرة في كل وقت", "هي كنز من كنوز الجنة."),
        "dua_la_mania" to DuaText("لا مانع لما أعطيت", "لا إله إلا الله وحده لا شريك له، له الملك وله الحمد وهو على كل شيء قدير، اللهم لا مانع لما أعطيت، ولا معطي لما منعت، ولا ينفع ذا الجد منك الجد", "بعد السلام من الصلاة المفروضة", "كان النبي ﷺ يقولها بعد كل صلاة فرض."),
        "dua_leaving_home_adilla" to DuaText("الاستعاذة من الضلال", "اللهم إني أعوذ بك أن أضل أو أضل، أو أزل أو أزل، أو أظلم أو أظلم، أو أجهل أو يجهل علي", "عند الخروج من المنزل — رواية أم سلمة رضي الله عنها", "كان النبي ﷺ يقولها كلما خرج من بيته."),
        "dua_leprosy_diseases" to DuaText("الاستعاذة من الأمراض الخطيرة", "اللهم إني أعوذ بك من البرص، والجنون، والجذام، ومن سيئ الأسقام", "الحفظ من الأمراض السيئة", "دعاء مسنون لحفظ الصحة."),
        "dua_love_for_allah" to DuaText("الرد على من قال 'أحبك في الله'", "أحبك الذي أحببتني له", "إذا قال أحد 'إني أحبك في الله'", "الرد المسنون على المحبة في الله."),
        "dua_mayyit_awf" to DuaText("دعاء مفصل للميت", "اللهم اغفر له وارحمه، وعافه واعف عنه، وأكرم نزله، ووسع مدخله، واغسله بالماء والثلج والبرد، ونقه من الخطايا كما نقيت الثوب الأبيض من الدنس", "في الجنازة أو للميت", "تمنى عوف بن مالك رضي الله عنه أن يكون هو الميت."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("اغفر لي ما قدمت وما أخرت", "اللهم اغفر لي ما قدمت وما أخرت، وما أسررت وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم وأنت المؤخر، لا إله إلا أنت", "بعد التشهد والصلاة على النبي ﷺ قبل السلام", "كان النبي ﷺ يقولها بين التشهد والسلام."),
        "dua_morning_blessing" to DuaText("شكر النعم صباحًا", "اللهم ما أصبح بي من نعمة أو بأحد من خلقك فمنك وحدك لا شريك لك فلك الحمد ولك الشكر", "ذكر شكر نعم الله في الصباح", "حصن المسلم."),
        "dua_morning_witness" to DuaText("إشهاد التوحيد صباحًا", "اللهم إني أصبحت أشهدك وأشهد حملة عرشك وملائكتك وجميع خلقك أنك أنت الله لا إله إلا أنت وحدك لا شريك لك وأن محمدا عبدك ورسولك", "يُذكر في الرواية قراءتها أربع مرات صباحًا", "حصن المسلم."),
        "dua_musarrifal_qulub" to DuaText("يا مصرّف القلوب صرّف قلوبنا", "اللهم مصرف القلوب صرف قلوبنا على طاعتك", "دعاء تثبيت القلب على الطاعة", "قلوب العباد بين إصبعين من أصابع الرحمن."),
        "dua_musa_faqir" to DuaText("دعاء موسى عليه السلام لطلب الرزق", "رب إني لما أنزلت إلي من خير فقير", "طلب الرزق والخير — دعاء موسى عليه السلام في مدين", "بعد هذا الدعاء رزقه الله بيتًا وعملًا وزوجة."),
        "dua_new_moon" to DuaText("عند رؤية الهلال", "اللهم أهله علينا باليمن والإيمان، والسلامة والإسلام، ربي وربك الله", "عند رؤية الهلال الجديد", "دعاء مسنون عند كل شهر جديد."),
        "dua_non_muslim_sneezes" to DuaText("إذا عطس غير المسلم", "يهديكم الله ويصلح بالكم", "إذا عطس غير المسلم وحمد الله", "كان اليهود يتحمدون عند النبي ﷺ فكان يقول هذا."),
        "dua_placing_in_grave" to DuaText("عند وضع الميت في القبر", "بسم الله وعلى ملة رسول الله", "عند إنزال الميت في القبر", "دعاء مسنون عند الدفن."),
        "dua_praising_someone" to DuaText("عند مدح أحد", "أحسب فلانا، والله حسيبه، ولا أزكي على الله أحدا", "عند الثناء على أحد دون مبالغة", "أدب المدح الذي علّمه النبي ﷺ."),
        "dua_qadarullah" to DuaText("عند وقوع أمر مكروه", "قدر الله وما شاء فعل", "إذا حدث أمر مكروه بدل قول 'لو'", "'لو' تفتح عمل الشيطان."),
        "dua_q_alayka_tawakkalna" to DuaText("عليك توكلنا (دعاء إبراهيم عليه السلام)", "ربنا عليك توكلنا وإليك أنبنا وإليك المصير (٤) ربنا لا تجعلنا فتنة للذين كفروا واغفر لنا ربنا ۖ إنك أنت العزيز الحكيم (٥)", "دعاء إبراهيم عليه السلام وأصحابه", "دعاء التوكل والإنابة."),
        "dua_q_amanna_faghfir" to DuaText("آمنا فاغفر لنا وارحمنا", "ربنا آمنا فاغفر لنا وارحمنا وأنت خير الراحمين", "دعاء عباد الله الصالحين", "دعاء جامع للمغفرة والرحمة."),
        "dua_q_aqraba_rashada" to DuaText("لعل ربي يهديني لأقرب من هذا رشدًا", "عسى أن يهدين ربي لأقرب من هذا رشدا", "عند البحث عن طريق أفضل في أمر ما", "علّمها النبي ﷺ عند النسيان."),
        "dua_q_ashku_bathhi" to DuaText("دعاء يعقوب عليه السلام: أشكو بثي وحزني إلى الله", "إنما أشكو بثي وحزني إلى الله", "عند شدة الحزن والفراق", "قالها يعقوب عليه السلام عند فراق يوسف عليه السلام."),
        "dua_q_asiya_baytan" to DuaText("دعاء آسية: بيت في الجنة", "رب ابن لي عندك بيتا في الجنة ونجني من فرعون وعمله ونجني من القوم الظالمين", "دعاء امرأة فرعون آسية", "جعلها الله مثلًا للمؤمنين."),
    )
}
